var tests = new (string Name, Action Run)[]
{
    ("Missing candidate is rejected before load", MissingFile),
    ("Hash mismatch is rejected before load", HashMismatch),
    ("Incompatible target is rejected before load", IncompatibleTarget),
    ("Correct hash without approval is rejected before load", UnapprovedCandidate),
    ("Approval for a different hash is rejected before load", ApprovalForDifferentHash),
    ("Rejected candidate leaves the last known good version for the next process", NextProcessRestoresLastKnownGood),
    ("Activation failure returns a host error and keeps no exception", ActivationFailure),
    ("Activation failure locks the process and keeps the previous record", ActivationFailureLocksTheProcess),
    ("A failed startup cannot select another version in-process", StartupActivationBoundary),
    ("A planned candidate is not loaded", PlanDoesNotLoad),
    ("A candidate outside the content root is rejected before load", OutsideContentRootRejected),
    ("Last known good outside the content root is rejected before load", LastKnownGoodOutsideContentRoot),
    ("Additional content is checked before load", AdditionalContentCheckedBeforeLoad),
    ("Startup falls back before load and not after activation failure", StartupFallsBackBeforeLoad),
    ("Tick fault returns a host error and keeps the version", TickFaultKeepsVersion),
    ("Host callback during tick returns a host-owned value", TickCallsHost),
    ("A stored host callback stays closed during a later tick", TickStoredCallbackStaysClosed),
    ("Host callback fault returns a host error and keeps the version", TickHostFault),
    ("Host interface during tick returns a host-owned value", TickCallsHostApi),
    ("A stored host object stays closed during a later tick", TickStoredHostStaysClosed),
