var failures = 0;
foreach (var (name, run) in tests)
{
    try
    {
        run();
        Console.WriteLine("PASS " + name);
    }
    catch (Exception exception)
    {
        failures++;
        Console.Error.WriteLine("FAIL " + name + ": " + exception);
    }
}
Console.WriteLine((tests.Length - failures) + "/" + tests.Length + " tests passed");
return failures == 0 ? 0 : 1;

void MissingFile()
{
    using var directory = new TestDirectory();
    var before = UpdateContextCount();
    var result = new TrustedUpdateProcess().TrySelectCandidate(
        Candidate("missing", new string('a', 64), Path.Combine(directory.Path, "absent.dll"), "TrustedUpdate.Good.Entry"),
        host, directory.Store, null);
    Check(result.Failure == TrustedUpdateFailure.MissingContent, result.ToString());
    Check(!File.Exists(directory.Store), "missing candidate wrote last known good");
    Check(UpdateContextCount() == before, "missing candidate created a load context");
    Check(!IsLoaded("TrustedUpdate.Good") && !IsLoaded("TrustedUpdate.Throwing"), "missing candidate loaded an assembly");
}

void HashMismatch()
{
    using var directory = new TestDirectory();
    var before = UpdateContextCount();
    var result = new TrustedUpdateProcess().TrySelectCandidate(
        Candidate("bad-hash", new string('b', 64), throwingPath, "TrustedUpdate.Throwing.Entry"),
        host, directory.Store, null);
    Check(result.Failure == TrustedUpdateFailure.ContentHashMismatch, result.ToString());
    Check(!File.Exists(directory.Store), "hash mismatch wrote last known good");
    Check(UpdateContextCount() == before, "hash mismatch created a load context");
    Check(!IsLoaded("TrustedUpdate.Throwing"), "hash mismatch loaded TrustedUpdate.Throwing");
}

void IncompatibleTarget()
{
    using var directory = new TestDirectory();
    var before = UpdateContextCount();
    var candidate = Candidate("wrong-target", Hash(goodPath), goodPath, "TrustedUpdate.Good.Entry") with
    {
        Target = new TrustedUpdateTarget("ios", "arm64")
    };
    var result = new TrustedUpdateProcess().TrySelectCandidate(candidate, host, directory.Store, null);
    Check(result.Failure == TrustedUpdateFailure.IncompatibleTarget, result.ToString());
    Check(!File.Exists(directory.Store), "incompatible target wrote last known good");
    Check(UpdateContextCount() == before, "incompatible target created a load context");
    Check(!IsLoaded("TrustedUpdate.Good"), "incompatible target loaded TrustedUpdate.Good");
}

void UnapprovedCandidate()
{
    using var directory = new TestDirectory();
    File.WriteAllText(directory.Store, "previous-good");
    var before = UpdateContextCount();
    var hash = Hash(goodPath);
    var result = new TrustedUpdateProcess().TrySelectCandidate(
        Candidate("good", hash, goodPath, "TrustedUpdate.Good.Entry"),
        host, directory.Store, null);
    Check(result.Failure == TrustedUpdateFailure.NotApproved, result.ToString());
    Check(File.ReadAllText(directory.Store) == "previous-good", "unapproved candidate rewrote last known good");
    Check(UpdateContextCount() == before, "unapproved candidate created a load context");
    Check(!IsLoaded("TrustedUpdate.Good"), "unapproved candidate loaded TrustedUpdate.Good");
}

void ApprovalForDifferentHash()
{
    using var directory = new TestDirectory();
    File.WriteAllText(directory.Store, "previous-good");
    var before = UpdateContextCount();
    var hash = Hash(throwingPath);
    var result = new TrustedUpdateProcess().TrySelectCandidate(
        Candidate("throwing", hash, throwingPath, "TrustedUpdate.Throwing.Entry"),
        host, directory.Store, new TrustedUpdateApproval("throwing", new string('d', 64), "desktop-test"));
    Check(result.Failure == TrustedUpdateFailure.NotApproved, result.ToString());
    Check(File.ReadAllText(directory.Store) == "previous-good", "mismatched approval rewrote last known good");
    Check(UpdateContextCount() == before, "mismatched approval created a load context");
    Check(!IsLoaded("TrustedUpdate.Throwing"), "mismatched approval loaded TrustedUpdate.Throwing");
}

void NextProcessRestoresLastKnownGood()
{
    using var directory = new TestDirectory();
    var firstMarker = Path.Combine(directory.Path, "first.txt");
    var selected = RunChild(firstMarker, "--child-activate", "good", goodPath, Hash(goodPath), "TrustedUpdate.Good.Entry", directory.Store);
    Check(selected.Contains("SELECTED good", StringComparison.Ordinal), selected);
    Check(File.ReadAllText(firstMarker) == "activated", "first process did not activate");
    var store = File.ReadAllText(directory.Store);

    var rejected = RunChild(null, "--child-activate", "bad", throwingPath, new string('c', 64), "TrustedUpdate.Throwing.Entry", directory.Store);
    Check(rejected.Contains("REJECTED ContentHashMismatch", StringComparison.Ordinal), rejected);
    Check(!rejected.Contains(PrivateFailure, StringComparison.Ordinal), rejected);
    Check(File.ReadAllText(directory.Store) == store, "rejected candidate changed last known good");
    Check(!IsLoaded("TrustedUpdate.Good") && !IsLoaded("TrustedUpdate.Throwing"), "parent loaded a candidate assembly");

    var restoredMarker = Path.Combine(directory.Path, "restored.txt");
    var restored = RunChild(restoredMarker, "--child-restore", directory.Store, "good", Hash(goodPath), "desktop-test");
    Check(restored.Contains("RESTORED good", StringComparison.Ordinal), restored);
    Check(File.ReadAllText(restoredMarker) == "activated", "next process did not activate last known good");
    Check(!IsLoaded("TrustedUpdate.Throwing"), "parent loaded the rejected assembly");
}

void ActivationFailure()
{
    using var directory = new TestDirectory();
    var output = RunChild(null, "--child-activate", "throwing", throwingPath, Hash(throwingPath), "TrustedUpdate.Throwing.Entry", directory.Store);
    Check(output.Contains("REJECTED ActivationFailed", StringComparison.Ordinal), output);
    Check(!output.Contains(PrivateFailure, StringComparison.Ordinal), output);
    Check(!File.Exists(directory.Store), "failed activation wrote last known good");
    Check(!IsLoaded("TrustedUpdate.Throwing"), "parent loaded the throwing update");
}

void ActivationFailureLocksTheProcess()
{
    using var directory = new TestDirectory();
    File.WriteAllText(directory.Store, "previous-good");
    var output = RunChild(null, "--child-fail-then-good", throwingPath, Hash(throwingPath), goodPath, Hash(goodPath), directory.Store);
    Check(output.Contains("REJECTED ActivationFailed", StringComparison.Ordinal), output);
    Check(output.Contains("REJECTED ProcessSelectionLocked", StringComparison.Ordinal), output);
    Check(output.Contains("STORE-SAME", StringComparison.Ordinal), output);
    Check(output.Contains("GOOD-NOT-LOADED", StringComparison.Ordinal), output);
    Check(!output.Contains("SELECTED", StringComparison.Ordinal), output);
    Check(!output.Contains(PrivateFailure, StringComparison.Ordinal), output);
    Check(File.ReadAllText(directory.Store) == "previous-good", "activation failure replaced the previous record");
    Check(!IsLoaded("TrustedUpdate.Throwing") && !IsLoaded("TrustedUpdate.Good"), "parent loaded a recovery assembly");
}

void StartupActivationBoundary()
{
