void OutsideContentRootRejected()
{
    using var directory = new TestDirectory();
    var inside = Path.Combine(directory.Path, "inside");
    var outside = Path.Combine(directory.Path, "outside");
    Directory.CreateDirectory(inside);
    Directory.CreateDirectory(outside);
    var dll = Path.Combine(inside, "TrustedUpdate.Good.dll");
    var outsideDll = Path.Combine(outside, "TrustedUpdate.Good.dll");
    File.Copy(goodPath, dll);
    File.Copy(goodPath, outsideDll);
    var hash = Hash(dll);
    var candidate = Candidate("rooted", hash, dll, "TrustedUpdate.Good.Entry");
    var approved = Approve("rooted", hash);
    var accepted = new TrustedUpdateProcess().TryPlanCandidate(candidate, host, approved, inside);
    Check(accepted.Succeeded && accepted.SelectedVersionName == "rooted", accepted.ToString());
    var nested = Path.Combine(inside, "nested");
    Directory.CreateDirectory(nested);
    var stillInside = Path.Combine(nested, "..", "TrustedUpdate.Good.dll");
    Check(stillInside.Contains("..", StringComparison.Ordinal), stillInside);
    var folded = Candidate("rooted", hash, stillInside, "TrustedUpdate.Good.Entry");
    var foldedPlan = new TrustedUpdateProcess().TryPlanCandidate(folded, host, approved, inside);
    Check(foldedPlan.Succeeded && foldedPlan.SelectedVersionName == "rooted", foldedPlan.ToString());
    var before = UpdateContextCount();
    var rejected = new TrustedUpdateProcess().TrySelectCandidate(candidate, host, directory.Store, approved, outside);
    Check(rejected.Failure == TrustedUpdateFailure.OutsideContentRoot, rejected.ToString());
    var escaped = Path.Combine(inside, "..", "outside", "TrustedUpdate.Good.dll");
    Check(escaped.Contains("..", StringComparison.Ordinal), escaped);
    var escapedCandidate = Candidate("rooted", hash, escaped, "TrustedUpdate.Good.Entry");
    var escapedRejected = new TrustedUpdateProcess().TrySelectCandidate(
        escapedCandidate, host, directory.Store, approved, inside);
    Check(escapedRejected.Failure == TrustedUpdateFailure.OutsideContentRoot, escapedRejected.ToString());
    Check(UpdateContextCount() == before, "outside root created a load context");
    Check(!IsLoaded("TrustedUpdate.Good"), "outside root loaded TrustedUpdate.Good");
    Check(!File.Exists(directory.Store), "outside root wrote last known good");
}

void LastKnownGoodOutsideContentRoot()
{
    using var directory = new TestDirectory();
    var inside = Path.Combine(directory.Path, "inside");
    var outside = Path.Combine(directory.Path, "outside");
    Directory.CreateDirectory(inside);
    Directory.CreateDirectory(outside);
    var dll = Path.Combine(inside, "TrustedUpdate.Good.dll");
    var outsideDll = Path.Combine(outside, "TrustedUpdate.Good.dll");
    File.Copy(goodPath, dll);
    File.Copy(goodPath, outsideDll);
    var hash = Hash(dll);
    var selected = RunChild(null, "--child-activate", "rooted", dll, hash, "TrustedUpdate.Good.Entry", directory.Store);
    Check(selected.Contains("SELECTED rooted", StringComparison.Ordinal), selected);
    var nested = Path.Combine(inside, "nested");
    Directory.CreateDirectory(nested);
    var escapedStore = Path.Combine(directory.Path, "escaped.json");
    var foldedStore = Path.Combine(directory.Path, "folded.json");
    WriteAssemblyPath(directory.Store, escapedStore, Path.Combine(inside, "..", "outside", "TrustedUpdate.Good.dll"));
    WriteAssemblyPath(directory.Store, foldedStore, Path.Combine(nested, "..", "TrustedUpdate.Good.dll"));
    var escapedText = File.ReadAllText(escapedStore);
    Check(escapedText.Contains("..", StringComparison.Ordinal), escapedText);
    var before = UpdateContextCount();
    var rejected = new TrustedUpdateProcess().TrySelectLastKnownGood(host, escapedStore, Approve("rooted", hash), inside);
    Check(rejected.Failure == TrustedUpdateFailure.OutsideContentRoot, rejected.ToString());
    Check(File.ReadAllText(escapedStore) == escapedText, "outside last known good was rewritten");
    Check(UpdateContextCount() == before, "outside last known good created a load context");
    Check(!IsLoaded("TrustedUpdate.Good"), "outside last known good loaded TrustedUpdate.Good");
    var foldedText = File.ReadAllText(foldedStore);
    Check(foldedText.Contains("..", StringComparison.Ordinal), foldedText);
    var restored = RunChild(null, "--child-restore-root", foldedStore, "rooted", hash, "desktop-test", inside);
    Check(restored.Contains("RESTORED rooted", StringComparison.Ordinal), restored);
    Check(File.ReadAllText(escapedStore) == escapedText, "inside restore rewrote the rejected store");
    Check(!IsLoaded("TrustedUpdate.Good"), "parent loaded TrustedUpdate.Good");
}

void AdditionalContentCheckedBeforeLoad()
{
    using var directory = new TestDirectory();
    var inside = Path.Combine(directory.Path, "inside");
    var outside = Path.Combine(directory.Path, "outside");
    Directory.CreateDirectory(inside);
    Directory.CreateDirectory(outside);
    var dll = Path.Combine(inside, "TrustedUpdate.Good.dll");
    File.Copy(goodPath, dll);
    var hash = Hash(dll);
    var extra = Path.Combine(inside, "TrustedUpdate.Private.dll");
    var outsideExtra = Path.Combine(outside, "TrustedUpdate.Private.dll");
    File.WriteAllText(extra, "private-v1");
    File.WriteAllText(outsideExtra, "private-v1");
    var extraHash = Hash(extra);
    var nested = Path.Combine(inside, "nested");
    Directory.CreateDirectory(nested);
    var stillInside = Path.Combine(nested, "..", "TrustedUpdate.Private.dll");
    var escaped = Path.Combine(inside, "..", "outside", "TrustedUpdate.Private.dll");
    Check(stillInside.Contains("..", StringComparison.Ordinal) && escaped.Contains("..", StringComparison.Ordinal), escaped);
    var approved = Approve("rooted", hash);
    var before = UpdateContextCount();
    var accepted = new TrustedUpdateProcess().TryPlanCandidate(
        Candidate("rooted", hash, dll, "TrustedUpdate.Good.Entry", new TrustedUpdateContentFile(stillInside, extraHash)),
        host, approved, inside);
    Check(accepted.Succeeded && accepted.SelectedVersionName == "rooted", accepted.ToString());
    var missing = new TrustedUpdateProcess().TrySelectCandidate(
        Candidate("rooted", hash, dll, "TrustedUpdate.Good.Entry", new TrustedUpdateContentFile(Path.Combine(inside, "absent.dll"), extraHash)),
        host, directory.Store, approved, inside);
    Check(missing.Failure == TrustedUpdateFailure.MissingContent, missing.ToString());
    var mismatched = new TrustedUpdateProcess().TrySelectCandidate(
        Candidate("rooted", hash, dll, "TrustedUpdate.Good.Entry", new TrustedUpdateContentFile(extra, new string('0', 64))),
        host, directory.Store, null, inside);
    Check(mismatched.Failure == TrustedUpdateFailure.ContentHashMismatch, mismatched.ToString());
    var outsideRejected = new TrustedUpdateProcess().TrySelectCandidate(
        Candidate("rooted", hash, dll, "TrustedUpdate.Good.Entry", new TrustedUpdateContentFile(escaped, extraHash)),
        host, directory.Store, approved, inside);
    Check(outsideRejected.Failure == TrustedUpdateFailure.OutsideContentRoot, outsideRejected.ToString());
    var store = Path.Combine(directory.Path, "stored.json");
    var text = JsonSerializer.Serialize(new Dictionary<string, object?>
    {
        ["VersionName"] = "rooted",
        ["ContentSha256"] = hash,
        ["AssemblyPath"] = dll,
        ["EntryTypeName"] = "TrustedUpdate.Good.Entry",
        ["EntryMethodName"] = "Activate",
        ["Runtime"] = "net11.0",
        ["Architecture"] = "x64",
        ["AdditionalContent"] = new[]
        {
            new Dictionary<string, string> { ["Path"] = extra, ["ContentSha256"] = new string('0', 64) },
        },
    });
    File.WriteAllText(store, text);
    var restored = new TrustedUpdateProcess().TrySelectLastKnownGood(host, store, approved, inside);
    Check(restored.Failure == TrustedUpdateFailure.ContentHashMismatch, restored.ToString());
    Check(File.ReadAllText(store) == text, "additional mismatch rewrote last known good");
    Check(UpdateContextCount() == before, "additional content created a load context");
    Check(!IsLoaded("TrustedUpdate.Good"), "additional content loaded TrustedUpdate.Good");
    Check(!File.Exists(directory.Store), "additional content wrote the selector store");
}

