}


void StartupFallsBackBeforeLoad()
{
    using var directory = new TestDirectory();
    var inside = Path.Combine(directory.Path, "inside");
    Directory.CreateDirectory(inside);
    var dll = Path.Combine(inside, "TrustedUpdate.Good.dll");
    File.Copy(goodPath, dll);
    var hash = Hash(dll);
    var selected = RunChild(null, "--child-activate", "rooted", dll, hash, "TrustedUpdate.Good.Entry", directory.Store);
    Check(selected.Contains("SELECTED rooted", StringComparison.Ordinal), selected);
    var missingStore = Path.Combine(directory.Path, "missing-store.json");
    var missing = RunChild(null, "--child-start", "bad", dll, new string('b', 64), "TrustedUpdate.Good.Entry", missingStore, inside, "rooted", hash);
    Check(missing.Contains("START None NoLastKnownGood ContentHashMismatch -", StringComparison.Ordinal), missing);
    var fallback = RunChild(null, "--child-start", "bad", dll, new string('b', 64), "TrustedUpdate.Good.Entry", directory.Store, inside, "rooted", hash);
    Check(fallback.Contains("START LastKnownGood None ContentHashMismatch rooted", StringComparison.Ordinal), fallback);
    var beforeActivation = File.ReadAllBytes(directory.Store);
    var throwingHash = Hash(throwingPath);
    var activation = RunChild(null, "--child-start", "throwing", throwingPath, throwingHash, "TrustedUpdate.Throwing.Entry", directory.Store, "-", "throwing", throwingHash);
    Check(activation.Contains("START None ActivationFailed None -", StringComparison.Ordinal), activation);
    Check(File.ReadAllBytes(directory.Store).AsSpan().SequenceEqual(beforeActivation), "activation failure changed last known good");
    Check(!IsLoaded("TrustedUpdate.Good") && !IsLoaded("TrustedUpdate.Throwing"), "parent loaded a startup assembly");
}

