void SelectAndBlockSwitch()
{
    using var directory = new TestDirectory();
    var marker = Path.Combine(directory.Path, "activated.txt");
    Environment.SetEnvironmentVariable("RUNECLR_TRUSTED_UPDATE_MARKER", marker);
    try
    {
        var process = new TrustedUpdateProcess();
        var goodHash = Hash(goodPath);
        var selected = process.TrySelectCandidate(
            Candidate("good", goodHash, goodPath, "TrustedUpdate.Good.Entry"), host, directory.Store, Approve("good", goodHash));
        Check(selected.Succeeded && selected.SelectedVersionName == "good", selected.ToString());
        Check(File.ReadAllText(marker) == "activated", "good candidate did not activate");
        Check(IsLoaded("TrustedUpdate.Good"), "selected assembly was not loaded");
        var store = File.ReadAllText(directory.Store);
        Check(!store.Contains(PrivateFailure, StringComparison.Ordinal), store);
        Check(!store.Contains("Exception", StringComparison.Ordinal), store);

        var before = UpdateContextCount();
        var blocked = process.TrySelectCandidate(
            Candidate("other", Hash(throwingPath), throwingPath, "TrustedUpdate.Throwing.Entry"), host, directory.Store, null);
        Check(blocked.Failure == TrustedUpdateFailure.ProcessSelectionLocked, blocked.ToString());
        Check(blocked.SelectedVersionName is null, blocked.ToString());
        Check(UpdateContextCount() == before, "in-process switch created a load context");
        Check(!IsLoaded("TrustedUpdate.Throwing"), "in-process switch loaded the other assembly");
        Check(File.ReadAllText(directory.Store) == store, "blocked switch changed last known good");
        Check(process.HasSelectedVersion && process.SelectedVersionName == "good", "selection was not retained");
        var residency = process.DescribeResidency();
        Check(residency is { VersionName: "good", ResidentUntilProcessExit: true, UnloadSupported: false, SameProcessSwitchSupported: false },
            "residency was not limited to the process lifetime");
        var session = process.OpenSession();
        Check(session is not null && session.VersionName == "good" && !session.Closed, "session did not open");
        if (session is null)
            throw new InvalidOperationException("session did not open");
        process.CloseSession();
        Check(session.Closed, "session was not closed");
        var reopened = process.OpenSession();
        Check(reopened is not null && !ReferenceEquals(reopened, session) && !reopened.Closed, "session was not replaced");

        var tick = process.TryTick(1);
        Check(tick.Succeeded && tick.Value == 8, "open session did not run the update tick");
        process.CloseSession();
        var closedTick = process.TryTick(1);
        Check(closedTick.Failure == TrustedUpdateFailure.SessionNotOpen && closedTick.Value == 0, "closed session still ran the update");
        Check(process.TryWork().Failure == TrustedUpdateFailure.SessionNotOpen, "closed session accepted work");
        var workCopied = false;
        try { process.CopyPendingWork(); }
        catch (InvalidOperationException exception) when (exception.Message == "The session is not open.") { workCopied = true; }
        Check(workCopied, "closed session copied pending work");
        var token = new object();
        Check(process.TryListen().Failure == TrustedUpdateFailure.SessionNotOpen, "closed session listened");
        Check(process.TryEchoGenericInt(1).Failure == TrustedUpdateFailure.SessionNotOpen, "closed session echoed an int");
        Check(process.TryEchoObject(token).Failure == TrustedUpdateFailure.SessionNotOpen, "closed session echoed an object");
        Check(process.TryEchoGenericObject(token).Failure == TrustedUpdateFailure.SessionNotOpen, "closed session echoed a generic object");
        Check(process.TryReleaseHeldObjects().Failure == TrustedUpdateFailure.SessionNotOpen, "closed session released objects");
        Check(process.DescribeResidency() is { VersionName: "good", ResidentUntilProcessExit: true, UnloadSupported: false },
            "closing a session unloaded the selected version");


        Check(typeof(TrustedUpdateProcess).GetMethods().All(method => method.Name != "Unload"), "unload is public");
        Check(HasNoExceptionStorage(process, selected), "host retained an update exception");
    }
    finally
    {
        Environment.SetEnvironmentVariable("RUNECLR_TRUSTED_UPDATE_MARKER", null);
    }
}



static int ChildTickHost(string path, string hash, string store)
{
    var process = new TrustedUpdateProcess();
    var selected = process.TrySelectCandidate(
        new TrustedUpdateCandidate("tick-host", hash, path, "TrustedUpdate.TickHost.Entry", "Activate", new TrustedUpdateTarget("net11.0", "x64")),
        new TrustedUpdateTarget("net11.0", "x64"), store, Approve("tick-host", hash));
    Console.WriteLine(selected.Succeeded ? "SELECTED " + selected.SelectedVersionName : "REJECTED " + selected.Failure);
    process.OpenSession();
    var calls = 0;
    var tick = process.TryTick(1, value =>
    {
        calls++;
        return value + 1;
    });
    Console.WriteLine(tick.Succeeded ? "TICK " + tick.Value : "TICK " + tick.Failure);
    var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic;
    var keepsDelegate = typeof(TrustedUpdateProcess).GetFields(flags).Any(field => typeof(Delegate).IsAssignableFrom(field.FieldType));
    Console.WriteLine(keepsDelegate ? "KEEPS-DELEGATE" : "NO-DELEGATE");
    var residency = process.DescribeResidency();
    Console.WriteLine(residency is { ResidentUntilProcessExit: true, UnloadSupported: false } ? "RESIDENT" : "NOT-RESIDENT");
    var closed = false;
    try
    {
        var assembly = AssemblyLoadContext.All
            .SelectMany(context => context.Assemblies)
            .First(item => item.GetName().Name == "TrustedUpdate.TickHost");
        var kept = assembly.GetType("TrustedUpdate.TickHost.Entry")!
            .GetField("Kept", BindingFlags.Public | BindingFlags.Static)!
            .GetValue(null) as Func<int, int>;
        kept!(9);
    }
    catch (InvalidOperationException exception) when (exception.Message == "host callback closed")
    {
        closed = true;
    }
    Console.WriteLine(closed && calls == 1 ? "LATE-CLOSED" : "LATE-OPEN");
    Console.WriteLine("CALLS " + calls);
    return tick.Value == 5 && !keepsDelegate && closed && calls == 1 ? 0 : 1;
}

static void WriteTickHost(string path)
{
    var builder = new PersistedAssemblyBuilder(
        new AssemblyName("TrustedUpdate.TickHost") { Version = new Version(1, 0, 0, 0) },
        typeof(object).Assembly);
    var module = builder.DefineDynamicModule("TrustedUpdate.TickHost");
    var type = module.DefineType("TrustedUpdate.TickHost.Entry", TypeAttributes.Public | TypeAttributes.Abstract | TypeAttributes.Sealed);
    var kept = type.DefineField("Kept", typeof(Func<int, int>), FieldAttributes.Public | FieldAttributes.Static);
    var activate = type.DefineMethod("Activate", MethodAttributes.Public | MethodAttributes.Static, typeof(void), Type.EmptyTypes);
    activate.GetILGenerator().Emit(OpCodes.Ret);
    var tick = type.DefineMethod("Tick", MethodAttributes.Public | MethodAttributes.Static, typeof(int), new[] { typeof(int), typeof(Func<int, int>) });
    var il = tick.GetILGenerator();
    il.Emit(OpCodes.Ldarg_1);
    il.Emit(OpCodes.Stsfld, kept);
    il.Emit(OpCodes.Ldarg_1);
    il.Emit(OpCodes.Ldarg_0);
    il.Emit(OpCodes.Callvirt, typeof(Func<int, int>).GetMethod("Invoke")!);
    il.Emit(OpCodes.Ldc_I4_3);
    il.Emit(OpCodes.Add);
    il.Emit(OpCodes.Ret);
    type.CreateType();
    builder.Save(path);
}

static void WriteTickStale(string path)
{
    var builder = new PersistedAssemblyBuilder(
        new AssemblyName("TrustedUpdate.TickStale") { Version = new Version(1, 0, 0, 0) },
        typeof(object).Assembly);
    var module = builder.DefineDynamicModule("TrustedUpdate.TickStale");
    var type = module.DefineType("TrustedUpdate.TickStale.Entry", TypeAttributes.Public | TypeAttributes.Abstract | TypeAttributes.Sealed);
    var phase = type.DefineField("Phase", typeof(int), FieldAttributes.Public | FieldAttributes.Static);
    var kept = type.DefineField("Kept", typeof(Func<int, int>), FieldAttributes.Public | FieldAttributes.Static);
    var saw = type.DefineField("Saw", typeof(int), FieldAttributes.Public | FieldAttributes.Static);
    var activate = type.DefineMethod("Activate", MethodAttributes.Public | MethodAttributes.Static, typeof(void), Type.EmptyTypes);
    activate.GetILGenerator().Emit(OpCodes.Ret);
    var invoke = typeof(Func<int, int>).GetMethod("Invoke")!;
    var tick = type.DefineMethod("Tick", MethodAttributes.Public | MethodAttributes.Static, typeof(int), new[] { typeof(int), typeof(Func<int, int>) });
    var il = tick.GetILGenerator();
    var later = il.DefineLabel();
    var afterCatch = il.DefineLabel();
    il.Emit(OpCodes.Ldsfld, phase);
    il.Emit(OpCodes.Brtrue, later);
    il.Emit(OpCodes.Ldarg_1);
    il.Emit(OpCodes.Stsfld, kept);
    il.Emit(OpCodes.Ldc_I4_1);
    il.Emit(OpCodes.Stsfld, phase);
    il.Emit(OpCodes.Ldarg_1);
    il.Emit(OpCodes.Ldarg_0);
    il.Emit(OpCodes.Callvirt, invoke);
    il.Emit(OpCodes.Ldc_I4_3);
    il.Emit(OpCodes.Add);
    il.Emit(OpCodes.Ret);
    il.MarkLabel(later);
    il.BeginExceptionBlock();
    il.Emit(OpCodes.Ldsfld, kept);
    il.Emit(OpCodes.Ldarg_0);
    il.Emit(OpCodes.Callvirt, invoke);
    il.Emit(OpCodes.Pop);
    il.Emit(OpCodes.Ldc_I4_1);
    il.Emit(OpCodes.Stsfld, saw);
    il.Emit(OpCodes.Leave, afterCatch);
    il.BeginCatchBlock(typeof(InvalidOperationException));
