static int ChildWorkTwice(string path, string hash, string store)
{
    var process = new TrustedUpdateProcess();
    var selected = process.TrySelectCandidate(
        new TrustedUpdateCandidate("work-twice", hash, path, "TrustedUpdate.WorkTwice.Entry", "Activate", new TrustedUpdateTarget("net11.0", "x64")),
        new TrustedUpdateTarget("net11.0", "x64"), store, Approve("work-twice", hash));
    Console.WriteLine(selected.Succeeded ? "SELECTED " + selected.SelectedVersionName : "REJECTED " + selected.Failure);
    process.OpenSession();
    var first = process.TryWork();
    Console.WriteLine(first.Succeeded ? "WORK " + first.Value : "WORK " + first.Failure);
    var pending = process.CopyPendingWork();
    if (pending.Length != 1)
    {
        Console.WriteLine("PENDING " + pending.Length);
        return 1;
    }
    process.CompleteWork(pending[0].Id, 4);
    var duplicate = false;
    try
    {
        process.CompleteWork(pending[0].Id, 9);
    }
    catch (InvalidOperationException exception) when (exception.Message == "The work is already complete.")
    {
        duplicate = true;
    }
    var failDuplicate = false;
    try
    {
        process.FailWork(pending[0].Id, 3);
    }
    catch (InvalidOperationException exception) when (exception.Message == "The work is already complete.")
    {
        failDuplicate = true;
    }
    Console.WriteLine(duplicate && failDuplicate ? "DUP-REJECTED" : "DUP-OPEN");
    var open = process.CopyPendingWork();
    Console.WriteLine("PENDING " + open.Length);
    var taken = process.TryWork();
    Console.WriteLine(taken.Succeeded ? "TAKE " + taken.Value : "TAKE " + taken.Failure);
    var takenRejected = false;
    try
    {
        process.CompleteWork(pending[0].Id, 1);
    }
    catch (ArgumentException exception) when (exception.Message.Contains("does not belong", StringComparison.Ordinal))
    {
        takenRejected = true;
    }
    Console.WriteLine(takenRejected ? "TAKEN-REJECTED" : "TAKEN-OPEN");
    var flags = BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic;
    var keepsException = false;
    foreach (var field in typeof(TrustedUpdateProcess).GetFields(flags))
    {
        if (field.GetValue(process) is Exception)
            keepsException = true;
    }
    Console.WriteLine(keepsException ? "KEEPS-EXCEPTION" : "NO-EXCEPTION");
    var residency = process.DescribeResidency();
    Console.WriteLine(residency is { VersionName: "work-twice", ResidentUntilProcessExit: true, UnloadSupported: false } ? "RESIDENT" : "NOT-RESIDENT");
    return selected.Succeeded && first.Value == 0 && duplicate && failDuplicate && open.Length == 0 && taken.Value == 4 && takenRejected && !keepsException ? 0 : 1;
}

