    var hidden = type.DefineField("Hidden", typeof(int), FieldAttributes.Public | FieldAttributes.Static);
    var host = type.DefineField("Host", typeof(int), FieldAttributes.Public | FieldAttributes.Static);
    var activate = type.DefineMethod("Activate", MethodAttributes.Public | MethodAttributes.Static, typeof(void), Type.EmptyTypes);
    activate.GetILGenerator().Emit(OpCodes.Ret);
    var privateTick = type.DefineMethod("Tick", MethodAttributes.Private | MethodAttributes.Static, typeof(int), new[] { typeof(int) });
    var privateIl = privateTick.GetILGenerator();
    privateIl.Emit(OpCodes.Ldsfld, hidden);
    privateIl.Emit(OpCodes.Ldc_I4_1);
    privateIl.Emit(OpCodes.Add);
    privateIl.Emit(OpCodes.Stsfld, hidden);
    privateIl.Emit(OpCodes.Ldarg_0);
    privateIl.Emit(OpCodes.Ret);
