    hostIl.Emit(OpCodes.Ldc_I4_1);
    hostIl.Emit(OpCodes.Add);
    hostIl.Emit(OpCodes.Stsfld, host);
    hostIl.Emit(OpCodes.Ldc_I4_2);
    hostIl.Emit(OpCodes.Ret);
    type.CreateType();
    builder.Save(path);
