    il.Emit(OpCodes.Pop);
    il.Emit(OpCodes.Ldarg_0);
    il.Emit(OpCodes.Ldstr, "second");
    il.Emit(OpCodes.Callvirt, request);
    il.Emit(OpCodes.Pop);
    il.Emit(OpCodes.Ldc_I4_0);
    il.Emit(OpCodes.Ret);
    il.MarkLabel(take);
    il.Emit(OpCodes.Ldc_I4_2);
    il.Emit(OpCodes.Stsfld, phase);
    EmitTake(il, tryTake, id, value, ok, succeeded, 7, bad);
    il.MarkLabel(second);
    EmitTake(il, tryTake, id, value, ok, succeeded, 4, bad);
    il.MarkLabel(bad);
    il.Emit(OpCodes.Ldc_I4_M1);
