static int ChildWork(string path, string hash, string store)
{
    var process = new TrustedUpdateProcess();
    var selected = process.TrySelectCandidate(
        new TrustedUpdateCandidate("work", hash, path, "TrustedUpdate.Work.Entry", "Activate", new TrustedUpdateTarget("net11.0", "x64")),
        new TrustedUpdateTarget("net11.0", "x64"), store, Approve("work", hash));
    Console.WriteLine(selected.Succeeded ? "SELECTED " + selected.SelectedVersionName : "REJECTED " + selected.Failure);
    process.OpenSession();
    var first = process.TryWork();
    Console.WriteLine(first.Succeeded ? "WORK " + first.Value : "WORK " + first.Failure);
    var late = false;
    try
    {
        var assembly = AssemblyLoadContext.All.SelectMany(context => context.Assemblies)
            .First(item => item.GetName().Name == "TrustedUpdate.Work");
        var kept = assembly.GetType("TrustedUpdate.Work.Entry")!.GetField("Kept")!.GetValue(null) as ITrustedUpdateWork;
        kept!.Request("late");
    }
    catch (InvalidOperationException exception) when (exception.Message == "The update work is closed.")
    {
        late = true;
    }
    Console.WriteLine(late ? "LATE-CLOSED" : "LATE-LIVE");
    var pending = process.CopyPendingWork();
    var named = pending.Length == 2 && pending.Any(item => item.Name == "load") && pending.Any(item => item.Name == "bad");
    Console.WriteLine(named ? "PENDING 2" : "PENDING " + pending.Length);
    process.CompleteWork(pending.Single(item => item.Name == "load").Id, 4);
    process.FailWork(pending.Single(item => item.Name == "bad").Id, 9);
