static bool LaterSubscriptionRejected(ITrustedUpdateSignals gate)
{
    var added = 0;
    try
    {
        gate.Signal += value => added += value;
    }
    catch (InvalidOperationException exception) when (exception.Message == "host callback closed" && added == 0)
    {
        try
        {
            Action<int> extra = value => added += value;
            gate.Signal -= extra;
        }
        catch (InvalidOperationException remove) when (remove.Message == "host callback closed")
        {
            var field = gate.GetType().GetField("signal", BindingFlags.Instance | BindingFlags.NonPublic);
            return field is not null && field.GetValue(gate) is null;
        }
    }

    return false;
}
