    handlerIl.Emit(OpCodes.Ldsfld, seen);
    handlerIl.Emit(OpCodes.Ldarg_0);
    handlerIl.Emit(OpCodes.Add);
    handlerIl.Emit(OpCodes.Stsfld, seen);
    handlerIl.Emit(OpCodes.Ret);
    var listen = type.DefineMethod("Listen", MethodAttributes.Public | MethodAttributes.Static, typeof(int), new[] { typeof(ITrustedUpdateSignals) });
    var il = listen.GetILGenerator();
    var later = il.DefineLabel();
    var afterCatch = il.DefineLabel();
    il.Emit(OpCodes.Ldsfld, phase);
    il.Emit(OpCodes.Brtrue, later);
    il.Emit(OpCodes.Ldarg_0);
    il.Emit(OpCodes.Stsfld, kept);
