    if (approvalSpec != "-")
    {
        var parts = approvalSpec.Split("\t");
        if (parts.Length != 3)
        {
            Console.WriteLine("PLAN InvalidCandidate");
            return 0;
        }
        approval = new TrustedUpdateApproval(parts[0], parts[1], parts[2]);
    }
    IReadOnlyList<TrustedUpdateContentFile>? additional = null;
    if (additionalSpec != "-")
    {
        var files = new List<TrustedUpdateContentFile>();
        foreach (var part in additionalSpec.Split('|', StringSplitOptions.RemoveEmptyEntries))
        {
            var fields = part.Split('\t');
            if (fields.Length != 2)
            {
                Console.WriteLine("PLAN InvalidCandidate");
                return 0;
            }
            files.Add(new TrustedUpdateContentFile(fields[0], fields[1]));
        }
        additional = files;
    }
    var before = UpdateContextCount();
    var candidate = new TrustedUpdateCandidate(version, hash, path, "TrustedUpdate.Plan.Entry", "Activate", new TrustedUpdateTarget(candidateRuntime, candidateArch), additional);
    var target = new TrustedUpdateTarget(hostRuntime, hostArch);
    var result = contentRoot == "-"
        ? new TrustedUpdateProcess().TryPlanCandidate(candidate, target, approval)
        : new TrustedUpdateProcess().TryPlanCandidate(candidate, target, approval, contentRoot);
    if (UpdateContextCount() != before || IsLoaded("TrustedUpdate.Plan"))
    {
        Console.WriteLine("PLAN Loaded");
        return 1;
    }
    Console.WriteLine("PLAN " + result.Failure);
    return 0;
}

static int ChildStart(string version, string assemblyPath, string hash, string entry, string store, string contentRoot, string approvalVersion, string approvalHash)
{
    string? root = contentRoot == "-" ? null : contentRoot;
    var result = new TrustedUpdateProcess().TryStart(
        Candidate(version, hash, assemblyPath, entry),
        new TrustedUpdateTarget("net11.0", "x64"),
        store,
        new TrustedUpdateApproval(approvalVersion, approvalHash, "desktop-test"),
        root);
    Console.WriteLine("START " + result.Source + " " + result.Failure + " " + result.CandidateFailure + " " + (result.SelectedVersionName ?? "-"));
    return 0;
}

static int ChildActivate(string version, string assemblyPath, string hash, string entry, string store)
{
    var result = new TrustedUpdateProcess().TrySelectCandidate(
        new TrustedUpdateCandidate(version, hash, assemblyPath, entry, "Activate", new TrustedUpdateTarget("net11.0", "x64")),
        new TrustedUpdateTarget("net11.0", "x64"), store, Approve(version, hash));
    Console.WriteLine(result.Succeeded ? "SELECTED " + result.SelectedVersionName : "REJECTED " + result.Failure);
    return 0;
}

static int ChildFailThenGood(string badPath, string badHash, string goodPath, string goodHash, string store)
{
    File.WriteAllText(store, "previous-good");
    var failed = new TrustedUpdateProcess().TrySelectCandidate(
        new TrustedUpdateCandidate("throwing", badHash, badPath, "TrustedUpdate.Throwing.Entry", "Activate", new TrustedUpdateTarget("net11.0", "x64")),
        new TrustedUpdateTarget("net11.0", "x64"), store, Approve("throwing", badHash));
    Console.WriteLine(failed.Succeeded ? "SELECTED " + failed.SelectedVersionName : "REJECTED " + failed.Failure);
    var recovered = new TrustedUpdateProcess().TrySelectCandidate(
        new TrustedUpdateCandidate("good", goodHash, goodPath, "TrustedUpdate.Good.Entry", "Activate", new TrustedUpdateTarget("net11.0", "x64")),
        new TrustedUpdateTarget("net11.0", "x64"), store, Approve("good", goodHash));
    Console.WriteLine(recovered.Succeeded ? "SELECTED " + recovered.SelectedVersionName : "REJECTED " + recovered.Failure);
    Console.WriteLine(File.ReadAllText(store) == "previous-good" ? "STORE-SAME" : "STORE-CHANGED");
    Console.WriteLine(IsLoaded("TrustedUpdate.Good") ? "GOOD-LOADED" : "GOOD-NOT-LOADED");
    return failed.Failure == TrustedUpdateFailure.ActivationFailed
        && recovered.Failure == TrustedUpdateFailure.ProcessSelectionLocked
        && File.ReadAllText(store) == "previous-good"
        && !IsLoaded("TrustedUpdate.Good") ? 0 : 1;
}

